"""Original systemic sclerosis questions for the sclerosis/myositis/overlap chapter."""
from qbank_authoring import question,ref
rows=[]
E=ref('EULAR systemic sclerosis treatment: 2023 update, published 2025','https://doi.org/10.1136/ard-2024-226430')
B=ref('BSR 2024 systemic sclerosis guideline','https://doi.org/10.1093/rheumatology/keae394')
I=ref('ACR/CHEST SARD-associated ILD screening guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC12646464/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A woman has Raynaud phenomenon, sclerodactyly, telangiectasia, reflux and dilated nailfold capillaries with dropout. Which diagnosis best unifies the findings?', 'Systemic sclerosis',[
 ('Primary Raynaud phenomenon','Primary Raynaud does not explain skin sclerosis and the associated structural microvascular/systemic findings.'),('Eosinophilic fasciitis','This more often has fascial induration with relative finger sparing and lacks the typical Raynaud/nailfold pattern.'),('Scleredema','This has a different skin distribution and does not usually produce the characteristic vascular phenotype.')],
 'Recognize vascular, fibrosing and immune disease together','**Raynaud plus sclerodactyly and abnormal nailfold microvasculature strongly supports systemic sclerosis.**',['The disease can affect lungs, heart, kidneys and gastrointestinal tract.','Skin findings alone do not describe the full organ burden.'], '**Perform systematic organ screening rather than wait for symptoms alone.**',['Assess lung function/imaging, blood pressure/renal function and cardiopulmonary risk.','Document the distribution and trajectory of skin involvement.'],[['Raynaud','Vasculopathy'],['Sclerodactyly','Cutaneous fibrosis'],['Nailfold dropout','Structural microvascular injury']],[B,I],style='clinical_scenario')

q('Which finding best distinguishes diffuse cutaneous from limited cutaneous systemic sclerosis?', 'Skin thickening extending proximal to the elbows or knees, often including the trunk',[
 ('Any interstitial lung disease','ILD can occur in either cutaneous subset.'),('Any esophageal dysmotility','GI involvement can occur in both subsets.'),('A positive ANA alone','ANA does not define the anatomical cutaneous subset.')],
 'Cutaneous subset is defined by skin distribution','**Diffuse cutaneous disease extends beyond the distal limb distribution of limited disease.**',['The subset informs risk but does not determine every organ outcome.','Limited cutaneous disease can still cause severe PAH, ILD or GI disease.'], '**Assess organ risk in both subsets.**',['Early rapid skin progression warrants particular attention.','Do not label limited cutaneous disease as universally mild.'],[['Limited','Distal limb/face distribution'],['Diffuse','Proximal limb or trunk thickening'],['Both','Potential major organ involvement']],[B])

q('Which autoantibody is most classically associated with limited cutaneous systemic sclerosis and increased PAH risk?', 'Anti-centromere',[
 ('Anti-topoisomerase I','This is particularly associated with ILD risk and often diffuse disease, though not exclusively.'),('Anti-RNA polymerase III','This is particularly associated with renal crisis and rapidly progressive skin disease.'),('Anti-Jo-1','This is an antisynthetase-associated antibody.')],
 'Antibodies refine risk rather than replace screening','**Anti-centromere is associated with a limited cutaneous phenotype and pulmonary vascular risk.**',['Antibody associations are probabilistic, not absolute.','A patient with any antibody pattern still needs comprehensive organ assessment.'], '**Screen for cardiopulmonary disease over time.**',['A declining DLCO or disproportionate breathlessness requires evaluation.','Do not assume one antibody eliminates the risk of other complications.'],[['Centromere','Limited phenotype/PAH association'],['Topoisomerase I','ILD association'],['RNA polymerase III','Renal crisis association']],[B])

q('A systemic sclerosis patient has anti-topoisomerase I antibodies. Which complication deserves particular surveillance?', 'Interstitial lung disease',[
 ('Congenital fetal heart block as the characteristic association','This is more directly associated with maternal anti-Ro/SSA.'),('Anti-CD20-associated HBV reactivation independent of treatment exposure','Reactivation depends on infection history and immunosuppressive exposure, not this antibody alone.'),('Isolated rheumatoid erosive arthritis as the inevitable outcome','This antibody does not establish RA or inevitable erosive arthritis.')],
 'Identify an ILD-associated serological profile','**Anti-topoisomerase I is a recognized marker of increased SSc-ILD risk.**',['Baseline HRCT and pulmonary function testing are important in systemic sclerosis.','Symptoms may underestimate early interstitial involvement.'], '**Follow physiological and radiological trends as appropriate.**',['Review FVC, DLCO, exercise tolerance and oxygenation.','Discuss progressive disease with a multidisciplinary team.'],[['Antibody','Supports ILD risk assessment'],['HRCT','Extent and pattern'],['PFTs','Function and progression']],[B,I])

q('Which autoantibody is particularly associated with scleroderma renal crisis and a close temporal association between cancer and systemic sclerosis onset?', 'Anti-RNA polymerase III',[
 ('Anti-centromere','This more commonly tracks a limited cutaneous/vascular phenotype.'),('Anti-Ro/SSA','This is linked to other autoimmune phenotypes and neonatal lupus risk.'),('Anti-HMGCR','This is associated with immune-mediated necrotizing myopathy.')],
 'Use antibody status to anticipate high-risk presentations','**Anti-RNA polymerase III is associated with renal crisis risk and cancer temporally close to disease onset in a subset.**',['The association does not mean every positive patient has cancer.','Age-appropriate and risk-directed cancer assessment remains necessary.'], '**Teach blood-pressure monitoring and renal warning symptoms.**',['Review rapid skin progression and glucocorticoid exposure.','Tailor malignancy assessment to clinical red flags and current guidance.'],[['RNA polymerase III','Renal crisis/cancer-temporal association'],['BP trend','Important early warning'],['Cancer assessment','Risk- and symptom-directed']],[B])

q('A patient with rapidly progressive diffuse systemic sclerosis develops BP 205/115 mmHg, acute kidney injury, schistocytes and thrombocytopenia after glucocorticoid exposure. What is the most likely diagnosis?', 'Scleroderma renal crisis',[
 ('Class IV lupus nephritis','This requires a compatible lupus phenotype and renal pathology; the stated sclerosis-hypertensive TMA presentation favors SRC.'),('Uncomplicated prerenal azotemia','This does not explain severe new hypertension and microangiopathic hemolysis.'),('Isolated acute interstitial nephritis','This is not the best explanation for this severe hypertension/TMA syndrome.')],
 'Recognize hypertensive renal TMA in systemic sclerosis','**Abrupt hypertension and AKI with microangiopathic features are characteristic of SRC.**',['A minority of cases are normotensive, so relative BP change and renal deterioration matter.','Glucocorticoid exposure, early diffuse disease and anti-RNA polymerase III increase concern.'], '**Start urgent ACE inhibitor-based treatment and obtain specialist care.**',['Assess volume status, cardiac effects and need for renal support.','Consider alternative TMAs when the presentation is atypical.'],[['SRC','New hypertension/AKI with possible MAHA'],['Risk factors','Early diffuse disease and steroid exposure'],['Urgent treatment','ACE inhibitor-based BP control']],[E,B],style='clinical_scenario')

q('Which treatment should be initiated promptly when scleroderma renal crisis is diagnosed?', 'An ACE inhibitor, commonly titratable captopril',[
 ('A high-dose glucocorticoid pulse as the defining first treatment','This is not the central SRC treatment and glucocorticoids can increase risk.'),('An ARB as an evidence-equivalent substitute in every patient','ACE inhibitors have the defining evidence and recommendation in SRC; substitution requires a specific reason.'),('A calcineurin inhibitor to suppress the renal microangiopathy','CNIs can worsen renal vascular and hypertensive problems and are not the defining SRC therapy.')],
 'Treat the renin-angiotensin-driven crisis','**ACE inhibition should be started immediately at SRC diagnosis.**',['Careful titration and additional BP agents may be necessary.','A creatinine rise does not automatically mean stopping the treatment that is central to the crisis plan.'], '**Manage perfusion, pressure and organ support together.**',['Dialysis may be required, and renal recovery can occur later in selected patients.','Routine prophylactic ACE inhibition before a crisis is not the same evidence-based indication.'],[['Established SRC','Prompt ACE inhibitor'],['Additional drugs','May be needed for BP control'],['Prophylaxis','Different question from treatment']],[E,B])

q('Which pharmacological option is a usual first-line choice for systemic sclerosis-related Raynaud symptoms?', 'A dihydropyridine calcium-channel blocker such as nifedipine',[
 ('Propranolol','Nonselective beta-blockade can aggravate peripheral vasospasm in susceptible patients.'),('High-dose systemic glucocorticoids','These are not standard vasospasm treatment and raise renal-crisis concerns.'),('Long-term cyclophosphamide solely for uncomplicated Raynaud','This exposes the patient to disproportionate toxicity without treating the main vasospastic mechanism.')],
 'Start with vascular and behavioral measures','**A dihydropyridine calcium-channel blocker is a standard initial drug choice.**',['Cold avoidance, warmth and smoking cessation are important.','PDE5 inhibitors or intravenous prostanoids can be considered for selected refractory/severe disease.'], '**Assess digital ischemia rather than treating every episode as uncomplicated vasospasm.**',['Ulceration, severe rest pain or threatened tissue needs urgent evaluation.','Review hypotension and interacting vasodilators.'],[['Uncomplicated Raynaud','CCB plus protection'],['Refractory disease','Consider further vasodilator options'],['Critical ischemia','Urgent specialist assessment']],[E,B])

q('In systemic sclerosis with recurrent digital ulcers, what is the principal evidence-based role of bosentan?', 'Reducing formation of new digital ulcers',[
 ('Reliably healing every established ulcer faster than wound care','The key evidence is prevention of new ulcers rather than a universal healing effect.'),('Reversing established pulmonary fibrosis','Bosentan is not an antifibrotic treatment for SSc-ILD.'),('Preventing renal crisis in all antibody-positive patients','This is not its established indication.')],
 'Distinguish ulcer prevention from ulcer healing','**Bosentan can reduce new SSc digital ulcer occurrence in selected patients.**',['Current ulcers need ischemia assessment, wound care and infection evaluation.','PDE5 inhibitors and intravenous iloprost may be considered for ulcer treatment according to the clinical context.'], '**Review liver safety, pregnancy risk and interactions.**',['Severe ischemic pain or necrosis requires urgent vascular/specialist care.','Treat calcinosis, trauma or infection when they contribute to a nonhealing lesion.'],[['Bosentan','New ulcer prevention'],['Established ulcer','Wound/vascular/infection care'],['Critical ischemia','Urgent escalation']],[E,B])

q('A systemic sclerosis patient has unexplained dyspnea, very low DLCO and relatively preserved lung volumes. What must be considered in addition to ILD?', 'Pulmonary arterial hypertension',[
 ('Pure chest-wall stiffness as the only plausible cause','A disproportionate DLCO reduction and dyspnea warrant pulmonary vascular evaluation.'),('Isolated reflux esophagitis','This does not explain the pulmonary physiological pattern.'),('Hydroxychloroquine retinal toxicity','This does not cause the stated lung physiology.')],
 'A disproportionate gas-transfer defect can be vascular','**PAH is a major systemic sclerosis complication that requires structured screening.**',['Echocardiography, biomarkers and validated algorithms can guide further assessment.','ILD, left-heart disease and chronic thromboembolism are alternative or coexisting mechanisms.'], '**Confirm suspected pulmonary hypertension with right-heart catheterization when indicated.**',['Hemodynamics distinguish precapillary from postcapillary disease.','Do not select PAH therapy solely from an echocardiographic pressure estimate.'],[['Low DLCO/preserved volumes','Consider pulmonary vascular disease'],['Echo/algorithms','Screening/assessment'],['RHC','Hemodynamic confirmation']],[B,ref('ESC/ERS pulmonary hypertension guideline: 2022','https://doi.org/10.1093/eurheartj/ehac237')],style='clinical_scenario')

q('Which test confirms the hemodynamic diagnosis and subtype of suspected systemic sclerosis-associated pulmonary hypertension?', 'Right-heart catheterization',[
 ('Echocardiography alone','It estimates probability and cardiac consequences but does not replace invasive hemodynamic confirmation.'),('Serum anti-centromere level alone','The antibody provides risk context, not pressure or resistance measurements.'),('A chest radiograph alone','It cannot define the hemodynamic subtype.')],
 'Treat the mechanism demonstrated by hemodynamics','**RHC measures pulmonary pressure, wedge pressure and cardiac output for classification.**',['Current precapillary definitions incorporate mean pulmonary pressure above 20 mmHg, PAWP at most 15 mmHg and elevated PVR above 2 Wood units.','SSc can produce more than one mechanism of pulmonary hypertension.'], '**Refer to a pulmonary hypertension center for diagnosis and therapy planning.**',['Risk-stratified combinations may include endothelin and nitric-oxide pathway treatments in PAH.','Do not use a PAH label indiscriminately for left-heart or severe lung-related PH.'],[['RHC','Defines pressures and resistance'],['PAWP','Helps distinguish left-heart contribution'],['PVR','Defines vascular component']],[ref('ESC/ERS pulmonary hypertension guideline: 2022','https://doi.org/10.1093/eurheartj/ehac237')])

q('Which treatment has evidence for slowing FVC decline in systemic sclerosis-associated ILD but is not expected to reverse all established fibrosis?', 'Nintedanib',[
 ('Bosentan','It is not the established antifibrotic treatment for this ILD indication.'),('Nifedipine','It treats vasospasm rather than the fibrotic lung process.'),('Captopril','Its defining systemic sclerosis role is renal-crisis treatment, not antifibrotic ILD therapy.')],
 'Slowing decline differs from restoring lost lung tissue','**Nintedanib is an antifibrotic option for SSc-ILD.**',['It may be used alone or with mycophenolate in an appropriate strategy.','Immunomodulatory options such as mycophenolate, rituximab or selected tocilizumab address other aspects of the disease.'], '**Choose by progression, inflammatory phenotype and tolerance.**',['Monitor gastrointestinal and hepatic adverse effects.','Track FVC/DLCO, symptoms and imaging when indicated rather than promising reversal of fibrosis.'],[['Nintedanib','Slows decline'],['Mycophenolate','Immunomodulatory option'],['Monitoring','Function, symptoms and safety']],[E,ref('SENSCIS original nintedanib trial','https://doi.org/10.1056/NEJMoa1903076')])

if __name__=='__main__':print(f'Systemic sclerosis draft: {len(rows)} questions')
